<?php use Simit\Core\Csrf; $old=$_SESSION['_old']??[];unset($_SESSION['_old']);$data=$old+$row; ?>
<div class="form-shell"><div class="form-intro"><a href="/<?=$module?>">← Kembali</a><h2><?=e($title)?></h2><p>Lengkapi informasi yang diperlukan. Kolom bertanda wajib harus diisi.</p></div><form class="panel form-grid" method="post" action="/<?=$module?>/save"><?=Csrf::field()?><input type="hidden" name="id" value="<?=$id?>"><?php foreach($config['fields'] as $field=>$label):?><label class="<?=in_array($field,['notes','description','instructions','result','findings'],true)?'full':''?>"><?=$label?><?php if(in_array($field,['code','name','title','number','event_date','inspected_at'],true)):?><sup>*</sup><?php endif;?><?php if(isset($config['options'][$field])):?><select name="<?=$field?>"><option value="">Pilih...</option><?php foreach($config['options'][$field] as $opt):?><option value="<?=e($opt['id'])?>" <?=((string)($data[$field]??'')===(string)$opt['id'])?'selected':''?>><?=e($opt['name'])?></option><?php endforeach;?></select><?php elseif(in_array($field,['notes','description','instructions','result','findings'],true)):?><textarea name="<?=$field?>" rows="4"><?=e($data[$field]??'')?></textarea><?php else:$type=str_contains($field,'_at')||$field==='event_date'||$field==='inspected_at'?'date':(in_array($field,['quantity','estimate_minutes','affected_count'],true)?'number':'text');?><input type="<?=$type?>" name="<?=$field?>" value="<?=e(isset($data[$field])&&$type==='date'?substr((string)$data[$field],0,10):($data[$field]??''))?>"><?php endif;?></label><?php endforeach;?><div class="form-actions full"><a class="btn ghost" href="/<?=$module?>">Batal</a><button class="btn primary">Simpan perubahan</button></div></form></div>

